import { button, coins, esc } from './views.js';
import { icon, brandMark } from './icons.js';

export function homeMenu(ui) {
  const d = ui.progress.data;
  const choices = [['club','Caddie','garage'],['gift','Shop','shop'],['trophy','Competitive','competitive'],['user','Multiplayer','multiplayer'],['play','Play','courses']];
  return `<main class="arcade-home"><div class="home-account">${coins(d.coins)}${button(esc(d.name) + ' · Lv ' + ui.progress.level.level,'profile','','home-profile')}${button(icon('sliders'),'settings','aria-label="Settings"','home-settings')}</div><section class="home-center"><h1>${brandMark()}<span>PolyGolf</span></h1><div id="home-splash" class="home-splash" hidden></div><nav class="home-tiles" aria-label="Main menu">${choices.map(([i,label,action])=>button(icon(i)+`<span>${label}</span>`,action,'','home-tile '+(action==='courses'?'home-play':''))).join('')}</nav><nav class="home-secondary" aria-label="More ways to play">${button(icon('flag')+'Editor','editor')}${button('Country Club','club-pass')}${button('Community maps','community')}${button('Friends','friends')}${button('Rankings','leaderboards')}</nav><div class="home-activity" id="online-estimate" hidden title="Studio-set activity estimate, not a live player count."><i></i><span>Online estimate · <b>-</b></span></div><div class="home-studio">Room310 × OneShotStudios</div>${button('Room310 community · Collect free coins','socials','','home-community')}</section><footer class="home-footer"><div>${button(ui.cloud.session ? 'Account' : 'Sign in / Create account','account')}${button('Controls','help')}${button(icon('fullscreen'),'fullscreen','aria-label="Fullscreen"')}</div><nav aria-label="Legal pages"><a href="/privacy.html">Privacy</a><a href="/terms.html">Terms</a><a href="/cookies.html">Cookies</a><a href="/copyright.html">Copyright</a><a href="/contact.html">Contact</a></nav></footer></main>`;
}
